#include <stdio.h>
void main() {
    int A[5] = {1, 2, 3, 4, 5};
    int B[5] = {6, 7, 8, 9, 10};
    int index = 0;
    while (index < 5) {
        printf("A[%d] = %d\n", index, A[index]);
        index = index + 1;
    }
    index = 0;
    while (index < 5) {
        printf("B[%d] = %d\n", index, B[index]);
        index = index + 1;
    }
    index = 0;
    printf("Displaying sum of elements of two arrays\n");
    while (index < 5) {
        printf("A[%d] + B[%d] = %d", index, index, A[index] + B[index]);
        index = index + 1;
    }
}
